# Closed storage program. Arguments are validated scalars generated by Rust.
set -eu
fs=$1 esp_uuid=$2 boot_uuid=$3 root_uuid=$4 disk_uuid=$5 root_end=$6 mode=$7
record() { printf '%s\n' "$1" >> /receipt; sync -f /receipt; }
# Pending destructive writes may only be accepted when their full probe passes.
step() {
    id=$1
    if grep -q "^ok:$id$" /receipt; then probe_$id; return; fi
    if grep -q "^start:$id$" /receipt; then probe_$id; record "ok:$id"; return; fi
    record "start:$id"
    do_$id
    probe_$id
    record "ok:$id"
}
part() {
    info=$(sgdisk --info="$1" /dev/borea-disk)
    printf '%s\n' "$info" | grep -qi "Partition GUID code: $2"
    printf '%s\n' "$info" | grep -q "First sector: $3 "
    printf '%s\n' "$info" | grep -q "Last sector: $4 "
}
probe_partition() {
    sgdisk --print /dev/borea-disk | grep -qi "Disk identifier (GUID): $disk_uuid"
    part 1 EF00 2048 2099199
    part 2 8300 2099200 6293503
    part 3 8300 6293504 "$root_end"
    sgdisk --verify /dev/borea-disk | grep -q 'No problems found'
}
do_partition() {
    sgdisk --clear --disk-guid="$disk_uuid" \
      --new=1:2048:2099199 --typecode=1:ef00 \
      --new=2:2099200:6293503 --typecode=2:8300 \
      --new=3:6293504:"$root_end" --typecode=3:8300 /dev/borea-disk
}
fat_id=$(printf '%s' "$esp_uuid" | cut -c1-8 | tr 'a-f' 'A-F')
fat_uuid=$(printf '%s' "$fat_id" | sed 's/\(....\)/\1-/;s/-$//')
probe_esp() {
    test "$(blkid -p -s TYPE -o value /dev/borea-esp)" = vfat
    test "$(blkid -p -s UUID -o value /dev/borea-esp)" = "$fat_uuid"
    fsck.fat -n /dev/borea-esp >/dev/null
}
do_esp() { mkfs.fat -F 32 -i "$fat_id" /dev/borea-esp; }
probe_boot() {
    test "$(blkid -p -s TYPE -o value /dev/borea-boot)" = ext4
    test "$(blkid -p -s UUID -o value /dev/borea-boot)" = "$boot_uuid"
    e2fsck -fn /dev/borea-boot >/dev/null
}
do_boot() { mkfs.ext4 -F -U "$boot_uuid" /dev/borea-boot; }
probe_root() {
    test "$(blkid -p -s TYPE -o value /dev/borea-root)" = "$fs"
    test "$(blkid -p -s UUID -o value /dev/borea-root)" = "$root_uuid"
    case "$fs" in btrfs) btrfs check --readonly /dev/borea-root >/dev/null ;; ext4) e2fsck -fn /dev/borea-root >/dev/null ;; esac
}
do_root() {
    case "$fs" in
      btrfs) mkfs.btrfs -U "$root_uuid" /dev/borea-root ;;
      ext4) mkfs.ext4 -F -U "$root_uuid" /dev/borea-root ;;
      *) exit 1 ;;
    esac
}
cleanup() { umount -R /target 2>/dev/null || :; }
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM HUP
step partition
step esp
step boot
step root
if test "$fs" = btrfs; then
    mount /dev/borea-root /target
    for sub in @ @home @snapshots @log @cache; do
        if test -e "/target/$sub"; then btrfs subvolume show "/target/$sub" >/dev/null
        else btrfs subvolume create "/target/$sub"; fi
    done
    umount /target
    mount -o subvol=@,compress=zstd /dev/borea-root /target
else mount /dev/borea-root /target; fi
mkdir -p /target/boot /target/etc /target/home /target/.snapshots /target/var/log /target/var/cache
mount /dev/borea-boot /target/boot
mkdir -p /target/boot/efi
mount /dev/borea-esp /target/boot/efi
if test "$fs" = btrfs; then
    for pair in '@home:home' '@snapshots:.snapshots' '@log:var/log' '@cache:var/cache'; do
        mount -o "subvol=${pair%%:*},compress=zstd" /dev/borea-root "/target/${pair#*:}"
    done
fi
{
    printf '# Borea disposable-image storage; no installed system yet\n'
    if test "$fs" = btrfs; then
        printf 'UUID=%s / btrfs defaults,subvol=@,compress=zstd 0 0\n' "$root_uuid"
        for pair in '@home:home' '@snapshots:.snapshots' '@log:var/log' '@cache:var/cache'; do
            printf 'UUID=%s /%s btrfs defaults,subvol=%s,compress=zstd 0 0\n' "$root_uuid" "${pair#*:}" "${pair%%:*}"
        done
    else printf 'UUID=%s / ext4 defaults 0 1\n' "$root_uuid"; fi
    printf 'UUID=%s /boot ext4 defaults 0 2\n' "$boot_uuid"
    printf 'UUID=%s /boot/efi vfat umask=0077 0 2\n' "$fat_uuid"
} > /target/etc/fstab.borea-tmp
chmod 644 /target/etc/fstab.borea-tmp
if test -e /target/etc/fstab; then
    cmp /target/etc/fstab.borea-tmp /target/etc/fstab
    rm /target/etc/fstab.borea-tmp
else mv /target/etc/fstab.borea-tmp /target/etc/fstab; fi
findmnt --mountpoint /target >/dev/null
findmnt --mountpoint /target/boot >/dev/null
findmnt --mountpoint /target/boot/efi >/dev/null
sync
cleanup
trap - EXIT
record verified
